# ---------------- 127.100 Construction Technology (Carpentry) ----------------
H('100.d.1.A',3,"A jobsite with a safety culture is one where workers:","Look out for their own and each other's safety every day",["Only follow rules when watched","Ignore hazards","Leave safety to inspectors"],"Safety culture means shared daily commitment.")
H('100.d.1.A',4,"A foreman stops work to fix an unguarded edge before continuing. This builds a:","Safety culture",["Production delay culture","Cost-cutting rule","Schedule myth"],"Leaders model safe priorities.")
H('100.d.1.B',3,"A strong safety culture is important in the crafts because it:","Reduces injuries and lost time",["Raises accident rates","Hides near misses","Removes training"],"Safe sites protect people and projects.")
H('100.d.1.B',4,"Workers who report near misses without fear of blame help to:","Prevent future injuries",["Create more hazards","Hide problems","Delay all projects"],"Open reporting finds hazards early.")
H('100.d.1.C',3,"OSHA stands for the:","Occupational Safety and Health Administration",["Open Shop Hazard Agency","Official Site Housing Authority","Outdoor Safety Home Association"],"OSHA sets and enforces workplace safety rules.")
H('100.d.1.C',4,"An OSHA inspector may visit a construction site to:","Check compliance with safety standards",["Sell tools","Hire workers","Set material prices"],"OSHA enforces standards.")
H('100.d.1.D',3,"A ladder used to reach an upper level should extend above the landing by:","About 3 feet",["Zero inches","One inch","Ten feet"],"Extension gives a handhold for stepping off.")
H('100.d.1.D',4,"Scaffold platforms over a certain height must have:","Guardrails or personal fall arrest",["No protection","Loose planks","Only tape"],"Edge protection prevents falls.")
H('100.d.1.E',3,"Hazard communication (HazCom) requires employers to:","Label chemicals and train workers on their hazards",["Hide chemical information","Remove all labels","Skip training"],"Workers have the right to know.")
H('100.d.1.E',4,"A container of stain with a missing label should be:","Reported and not used until identified",["Used anyway","Poured out","Mixed with others"],"Unlabeled chemicals are unsafe.")
H('100.d.1.F',3,"A Safety Data Sheet (SDS) for a glue tells workers about:","Its hazards, handling, and first aid",["Its price","Its color","Its delivery date"],"SDS lists safety information.")
H('100.d.1.F',4,"Section 4 of an SDS typically covers:","First-aid measures",["Shipping rates","Product slogan","Store locations"],"First-aid steps are given in a set section.")
H('100.d.1.G',3,"OSHA's General Duty Clause requires employers to provide a workplace free from:","Recognized serious hazards",["Customers","Paperwork","Deadlines"],"Employers must protect workers from known hazards.")
H('100.d.1.G',4,"The General Duty Clause applies even when:","No specific OSHA standard covers the hazard",["Every standard exists","The site is empty","The job is done"],"It fills gaps in specific standards.")
H('100.d.1.H',3,"OSHA 1926 is the set of safety standards for:","Construction",["Farming","Shipping","Schools"],"Part 1926 governs construction.")
H('100.d.1.H',4,"Subpart C of 1926 covers general safety and health provisions, including the employer's duty to:","Provide training and safe tools",["Collect taxes","Set prices","Choose paint colors"],"Subpart C sets basic duties.")
H('100.d.1.I',3,"Most jobsite accidents are caused by unsafe acts and:","Unsafe conditions",["Good weather","Safe tools","Clear plans"],"Both acts and conditions lead to accidents.")
H('100.d.1.I',4,"Rushing a cut by removing a saw guard is an example of an:","Unsafe act",["Unsafe condition","Safe habit","Required step"],"The worker's choice created the hazard.")
H('100.d.1.J',3,"Direct accident costs include medical bills and:","Workers' compensation",["Free equipment","Extra profit","Lunch savings"],"Direct costs are insured expenses.")
H('100.d.1.J',4,"Indirect accident costs include:","Lost production and replacement training",["Only hospital bills","Only fines","Insurance premiums only"],"Indirect costs often exceed direct ones.")
H('100.d.1.K',3,"A struck-by hazard occurs when a worker is hit by:","A moving or falling object",["Warm air","Quiet sounds","Soft light"],"Struck-by injuries involve impact.")
H('100.d.1.K',4,"Hard hats help to protect against:","Struck-by head injuries",["Chemical burns","Hearing loss","Heat only"],"Hard hats absorb impact.")
H('100.d.1.L',3,"A caught-in-between hazard includes:","Being crushed by equipment or a trench cave-in",["A paper cut","A sunburn","A sneeze"],"Caught-in hazards compress the body.")
H('100.d.1.L',4,"Trenches deeper than five feet require:","Protective systems such as shoring",["No protection","Only warning tape","Extra tools"],"Trench walls can collapse.")
H('100.d.1.M',3,"Other construction hazards on a site include asbestos, lead, and:","Silica dust",["Fresh air","Daylight","Birdsong"],"Dusts and toxic materials are hazards.")
H('100.d.1.M',4,"Disturbing old paint in older buildings may release:","Lead dust",["Helium","Carbon dioxide only","Pollen"],"Lead paint is a known hazard.")
H('100.d.1.N',3,"A safe work practice around electrical hazards is to:","Stay clear of overhead power lines",["Touch live wires","Use wet cords","Bypass breakers"],"Distance prevents contact.")
H('100.d.1.N',4,"Before working on a circuit, a worker should use:","Lockout and tagout",["Wet gloves","A damp ladder","Extra lights"],"Lockout keeps power off.")
H('100.d.1.O',3,"Hazard recognition means:","Spotting dangers before they cause harm",["Ignoring dangers","Waiting for injuries","Hiding hazards"],"Identify early to prevent harm.")
H('100.d.1.O',4,"A walkthrough of the site each morning is a way to:","Find new hazards before work starts",["Slow down progress","Avoid planning","Avoid reporting"],"Daily checks catch changes.")
H('100.d.1.P',3,"Risk assessment compares the likelihood of harm with its:","Severity",["Color","Cost of lunch","Brand"],"Risk equals likelihood and severity.")
H('100.d.1.P',4,"A task that is likely to occur and could cause serious injury is a:","High-risk task",["Low-risk task","No-risk task","Approved shortcut"],"High likelihood and severity mean high risk.")
H('100.d.1.Q',3,"Personal protective equipment should be:","Inspected before use and kept clean",["Worn damaged","Shared dirty","Stored wet"],"PPE must be in good condition.")
H('100.d.1.Q',4,"Safety glasses must meet:","The ANSI Z87 standard",["No standard","Fashion standards","Cost standards"],"Z87 rates impact protection.")
H('100.d.2.A',3,"One job duty of a carpenter is to:","Build and repair structures made of wood",["Prepare tax returns","Draw blood","Fly aircraft"],"Carpenters frame and finish.")
