H('100.d.2.B',4,"Experience and job skills for a carpenter include:","Reading plans, measuring accurately, and using tools safely",["Singing","Cooking","Painting portraits"],"Core skills for the trade.")
H('100.d.3.A',3,"Which building material is used for framing walls in houses?","Dimensional lumber",["Cotton","Foam peanuts","Clay pots"],"Studs are dimensional lumber.")
