H('100.d.3.B',4,"Pine and fir are softwoods commonly used for:","Framing lumber",["Piano keys only","Jewelry boxes only","Violins only"],"Softwoods are the standard for framing.")
H('100.d.3.C',3,"A lumber grade stamp indicates the board's:","Quality and species group",["Delivery date","Owner","Price"],"Stamps tell grade and species.")
