H('100.d.9.D',3,"Rebar is placed in concrete because concrete is weak in:","Tension",["Compression","Color","Weight"],"Steel resists pulling forces.")
H('100.d.9.D',4,"Fiber additives in concrete help to:","Reduce shrinkage cracks",["Add color","Add weight","Increase water"],"Fibers control cracking.")
H('100.d.9.E',3,"A spread footing is wider than the wall above to:","Distribute the load over more soil",["Save concrete","Hold paint","Reduce depth"],"Wide bases reduce soil pressure.")
H('100.d.9.E',4,"A footing must be placed below the:","Frost line",["Roof line","Water line","Fence line"],"Frost heave can damage footings.")
H('100.d.9.F',3,"The parts of a wall form include sheathing, studs, and:","Wales",["Shingles","Paint","Hinges"],"Wales stiffen the form.")
H('100.d.9.F',4,"A form tie holds opposite form faces:","Together at the proper spacing",["Apart","At random","At the roof"],"Ties set wall thickness.")
H('100.d.9.G',3,"On a concrete job, eye protection is needed because of:","Splashing wet concrete and flying debris",["Quiet noise","Dim light","Cold air only"],"Wet cement irritates eyes.")
H('100.d.9.G',4,"Form collapse is prevented by:","Proper bracing and following the form design",["Hoping","Speeding","Skipping ties"],"Bracing resists concrete pressure.")
H('100.d.9.H',3,"Reinforcement is held in place within a form with:","Chairs and tie wire",["Tape","Glue","Rope"],"Chairs set cover.")
H('100.d.9.H',4,"Checking that a form is plumb before the pour prevents:","A crooked finished wall",["Fast curing","Painting","Cracks of color"],"Plumb forms give straight walls.")
H('100.d.10.A',3,"A window that does not open is a:","Fixed window",["Casement","Slider","Hopper"],"Fixed windows are stationary.")
H('100.d.10.A',4,"A double-hung window opens by sliding:","Sashes up and down",["Left and right","Outward","Inward"],"Double-hung sashes are vertical sliders.")
H('100.d.10.B',3,"Parts of a window installation include the head, jamb, and:","Sill",["Rafter","Joist","Sole plate"],"Frame parts surround the sash.")
H('100.d.10.B',4,"Flashing is installed to keep water out at the:","Top and sides of the window",["Interior only","Ceiling","Floor"],"Flashing sheds water.")
H('100.d.10.C',3,"A window must be installed:","Plumb, level, and square",["Crooked","Loose","Unsealed"],"Correct fit ensures operation.")
H('100.d.10.C',4,"Shims are placed behind the window frame at the:","Corners and mid points to hold alignment",["Glass","Screen","Handle"],"Shims keep the frame true.")
H('100.d.10.D',3,"The first step in installing a pre-hung window is to check the:","Rough opening size",["Paint","Price","Weather"],"Opening must match the unit.")
H('100.d.10.D',4,"A pre-hung window's nailing fin is fastened to the:","Sheathing and framing",["Glass","Curtains","Trim"],"Fins attach the frame.")
H('100.d.10.E',3,"Exterior doors can be made of wood, steel, or:","Fiberglass",["Paper","Wool","Tissue"],"Fiberglass is durable.")
H('100.d.10.E',4,"A steel door skin is usually bonded to a core of:","Foam insulation",["Water","Sand","Paper"],"Foam adds R-value.")
H('100.d.10.F',3,"The doorframe parts include the head jamb, side jambs, and:","Threshold",["Rafter","Joist","Header only"],"The threshold is at the bottom.")
H('100.d.10.F',4,"Weatherstripping around a door reduces:","Air leaks",["Color","Weight","Cost"],"Stripping seals gaps.")
H('100.d.10.G',3,"A threshold is the part at the:","Bottom of the door opening",["Top of the opening","Side of the frame","Peak of the roof"],"The sill-level piece.")
H('100.d.10.G',4,"An adjustable threshold lets the installer:","Set the door-bottom seal",["Change door color","Reduce door weight","Lengthen the frame"],"Adjustment ensures a tight seal.")
H('100.d.10.H',3,"Hinge-side jambs of a pre-hung door are secured first to keep the door:","Plumb and aligned",["Loose","Uneven","Crooked"],"Hinge side sets alignment.")
H('100.d.10.H',4,"After installation, a properly hung door should:","Swing freely and latch without binding",["Stick","Scrape the floor","Stay open only"],"Function check.")
H('100.d.10.I',3,"A lockset with a deadbolt provides added:","Security",["Weight","Noise","Light"],"Deadbolts resist forced entry.")
H('100.d.10.I',4,"A cylindrical lockset installs through a:","Bored hole in the door face",["Roof","Frame only","Floor"],"Bored holes house the latch.")
H('100.d.10.J',3,"Before drilling for a lockset, use the:","Template provided",["Memory","Random marks","Crayon"],"Templates ensure accuracy.")
H('100.d.10.J',4,"A hole saw is used to bore the:","Large hole for the lockset",["Small pilot hole only","Roof vent","Window"],"Hole saws cut 2-1/8 inch holes.")
H('100.d.10.K',3,"Weatherstrip, flashing, and sealant are used on windows and doors to:","Keep out air and water",["Add noise","Add weight","Show color"],"They seal openings.")
H('100.d.10.K',4,"Flashing tape applied around a window opening should be lapped so that water:","Sheds outward",["Collects inside","Pools at the sill","Is trapped"],"Shingle-style laps shed water.")
H('100.d.11.A',3,"A staircase that has no turn is a:","Straight run stair",["Spiral stair","U-shaped stair","L-shaped stair"],"Straight runs go in one direction.")
H('100.d.11.A',4,"A stair that makes a 180-degree turn with a landing is a:","U-shaped stair",["Straight stair","Spiral stair","Ladder"],"U stairs reverse direction.")
H('100.d.11.B',3,"The tread is the part of a step that you:","Walk on",["Look through","Climb under","Hold onto"],"Treads carry feet.")
H('100.d.11.B',4,"The stringer is the angled member that:","Supports the treads and risers",["Covers the wall","Holds the rail only","Is a handrail"],"Stringers carry the steps.")
H('100.d.11.C',3,"Interior stairs are often built from:","Wood",["Cardboard","Foam","Cloth"],"Wood is common.")
H('100.d.11.C',4,"Exterior stairs are often built from pressure-treated wood or:","Concrete",["Paper","Cloth","Foam"],"Weather-resistant materials are needed.")
H('100.d.11.D',3,"A stair detail on a drawing shows the:","Rise, run, and landing locations",["Wallpaper","Sofa","Plumbing"],"Details give stair data.")
H('100.d.11.D',4,"The headroom on a stair plan must meet:","Minimum code clearance",["No limit","Unlimited height","Paint rules"],"Codes set headroom.")
H('100.d.11.E',3,"A total rise of 105 inches with 7-inch risers needs how many risers?","15",["7","12","10"],"105 / 7 = 15.")
H('100.d.11.E',4,"If a stair has 15 risers and 10-inch treads, the number of treads is usually:","14",["15","16","10"],"Treads are one fewer than risers.")
H('100.d.11.F',3,"To lay out stringers, a carpenter uses a framing square with:","Stair gauges",["Mallet","Trowel","Plane"],"Gauges set rise and run.")
H('100.d.11.F',4,"Each step cut into a stringer must have the same:","Rise and run",["Color","Weight","Width of rail"],"Uniform steps prevent trips.")
H('100.d.11.G',3,"A temporary handrail on a stair unit during construction protects workers from:","Falls",["Rain","Noise","Cold"],"Rails prevent falls.")
H('100.d.11.G',4,"A small stair unit should be built from:","Approved plans and measurements",["Memory","Guesses","Scrap"],"Plans guide construction.")

# ---------------- 127.104 Masonry I ----------------
H('104.d.1.A',3,"A six-foot folding rule is read in:","Inches and fractions of an inch",["Pounds","Degrees","Colors"],"The rule shows inch marks.")
H('104.d.1.A',4,"Each small mark between inches on a standard rule often equals:","1/16 inch",["1/2 inch","1/4 inch","1 inch"],"Sixteenths are common.")
H('104.d.1.B',3,"A steel tape measure is used to:","Measure longer distances",["Cut tile","Mix mortar","Hold a level"],"Tapes extend for long runs.")
H('104.d.1.B',4,"A level with a measuring edge helps to check:","Plumb and level",["Taste","Color","Weight"],"Levels check alignment.")
H('104.d.1.C',3,"A mason's rule is marked to show:","Course heights",["Colors","Prices","Weights"],"Spacing marks guide courses.")
H('104.d.1.C',4,"On a mason's rule, the course marks account for:","Brick height plus the mortar joint",["Only the brick","Only the mortar","Neither"],"Spacing includes joint thickness.")
H('104.d.1.D',3,"The 3-4-5 method squares a corner using sides of 3 feet, 4 feet, and a diagonal of:","5 feet",["6 feet","7 feet","4 feet"],"3-4-5 is a right triangle.")
H('104.d.1.D',4,"If the diagonal of a layout is longer than 5 feet using 3 and 4, the corner is:","More than 90 degrees",["Exactly 90 degrees","Less than 90 degrees","Flat"],"A longer diagonal means a wider angle.")
H('104.d.1.E',3,"Modular increments allow masonry to be built with fewer:","Cuts",["Bricks","Joints","Tools"],"Modular design reduces cutting.")
H('104.d.1.E',4,"A 4-inch module is commonly used so that wall dimensions are multiples of:","4 inches",["5 inches","7 inches","9 inches"],"Modular coordination.")
H('104.d.1.F',3,"The area of a rectangle is found by multiplying:","Length by width",["Length plus width","Width minus length","Length by itself"],"A = l x w.")
H('104.d.1.F',4,"The circumference of a circle is:","Pi times the diameter",["Pi plus diameter","Diameter squared","Radius only"],"C = pi d.")
H('104.d.1.G',3,"A set of drawings typically includes plans, elevations, sections, and:","Details",["Songs","Recipes","Posters"],"Sets contain multiple view types.")
H('104.d.1.G',4,"A title block on a drawing sheet shows the:","Project name, sheet number, and scale",["Weather","Mortar mix","Brick color"],"Title blocks identify sheets.")
H('104.d.1.H',3,"The lines, symbols, and abbreviations on drawings are explained in the:","Legend",["Menu","Title","Footer"],"Legends define symbols.")
H('104.d.1.H',4,"The abbreviation 'CMU' on a plan stands for:","Concrete masonry unit",["Cement mixing unit","Clay mortar unit","Corner mortar unit"],"CMU abbreviates concrete block.")
H('104.d.1.I',3,"A drawing scale of 1/4 inch = 1 foot means 1 inch on paper equals:","4 feet",["1 foot","2 feet","8 feet"],"1 / 0.25 = 4.")
H('104.d.1.I',4,"A wall 20 feet long on a drawing at 1/8 inch = 1 foot measures:","2.5 inches",["1 inch","5 inches","10 inches"],"20 x 0.125 = 2.5.")
H('104.d.1.J',3,"A floor plan view shows the building as if cut:","Horizontally and viewed from above",["Vertically","Diagonally","Upside down"],"Plans are top views.")
H('104.d.1.J',4,"A wall section is a drawing that shows the wall:","Cut through to reveal its layers",["From a satellite","As a photograph","With only paint"],"Sections show internal layers.")
H('104.d.1.K',3,"Standards and codes for masonry help ensure:","Safe and consistent construction",["Higher costs only","Slower work","Lower quality"],"They set minimum requirements.")
H('104.d.1.K',4,"Project specifications may call for masonry units that meet a standard such as:","ASTM",["Menu","Playbook","Almanac"],"ASTM standards define unit quality.")
H('104.d.1.L',3,"Specifications for a masonry job define the quality of:","Materials and workmanship",["Weather","Mood","Wages"],"Specs set the bar.")
H('104.d.1.L',4,"When specs and drawings differ on mortar type, the mason should:","Ask for clarification before proceeding",["Choose any","Ignore both","Use the cheaper"],"Resolve conflicts first.")
H('104.d.1.M',3,"Inspections of masonry work are done to verify:","Compliance with plans and codes",["Wages","Weather","Lunch breaks"],"Inspectors check quality.")
H('104.d.1.M',4,"Testing mortar cubes in a lab checks the mortar's:","Compressive strength",["Color","Smell","Cost"],"Strength tests confirm quality.")
H('104.d.2.A',3,"Mortar is mostly made from Portland cement, hydrated lime, and:","Sand",["Gravel","Paint","Salt"],"Sand is the main aggregate.")
H('104.d.2.A',4,"Lime in mortar helps to improve:","Workability and water retention",["Weight only","Color only","Freezing"],"Lime makes mortar plastic.")
H('104.d.2.B',3,"Masonry cement is a blend that already contains:","Plasticizers and lime-like materials",["Gravel","Paint","Glass"],"It simplifies batching.")
H('104.d.2.B',4,"Masonry cement is bagged and usually mixed with:","Sand and water",["Gravel and sugar","Tar","Sod"],"Add sand and water on site.")
H('104.d.2.C',3,"Pre-blended mortars are premixed at the factory to ensure:","Consistent proportions",["More mess","More errors","Hidden cost"],"Factory blends are uniform.")
H('104.d.2.C',4,"A bagged pre-blended mortar only needs the mason to add:","Water",["Rocks","Wood","Paper"],"It is a dry mix.")
H('104.d.2.D',3,"Water used in mortar should be:","Clean and free of harmful materials",["Muddy","Salty","Oily"],"Contaminants weaken mortar.")
H('104.d.2.D',4,"Admixtures in mortar are added to change properties such as:","Set time or workability",["Color of the sky","Brick size","Sand color"],"Admixtures modify performance.")
H('104.d.2.E',3,"The common mortar types are M, S, N, O, and:","K",["A","B","Z"],"ASTM mortar types.")
H('104.d.2.E',4,"Type S mortar is used for:","Structural or below-grade applications",["Decorative trim","Chimney flues","Painting"],"Type S has higher strength.")
H('104.d.2.F',3,"Plastic mortar should be workable and able to:","Hold the weight of units",["Run like water","Fall apart","Crumble"],"It should be cohesive.")
H('104.d.2.F',4,"Good water retention in plastic mortar keeps it from:","Drying out too quickly on the block",["Growing","Freezing in July","Turning blue"],"Retention helps bond.")
H('104.d.2.G',3,"Hardened mortar must have good:","Bond strength",["Taste","Noise","Odor"],"Bond holds units together.")
H('104.d.2.G',4,"Hardened mortar should also be:","Durable against weather",["Edible","Soft","Brittle"],"Durability matters.")
H('104.d.2.H',3,"A common mortar problem is mortar that is too wet, which can cause:","Slumping and weak joints",["Stronger joints","No change","Faster curing"],"Too much water weakens it.")
H('104.d.2.H',4,"If mortar begins to stiffen on the board, it can be:","Retempered with water within allowable time",["Dumped on the wall","Mixed with cement","Frozen"],"Retempering is allowed briefly.")
H('104.d.2.I',3,"Too much sand in a mix tends to make mortar:","Harsh and weak",["Sticky and strong","Perfect","Colorful"],"Proportions matter.")
H('104.d.2.I',4,"Poor-quality sand with clay or silt can cause:","Weak bond and cracking",["Stronger walls","Brighter color","Faster set"],"Contaminated sand harms mortar.")
H('104.d.2.J',3,"In hot, windy weather mortar tends to:","Dry out too fast",["Never set","Freeze","Become sweet"],"Evaporation is rapid.")
H('104.d.2.K',3,"Efflorescence is a:","White powdery deposit of salts on masonry",["Type of brick","Mortar color","Roof"],"Salts migrate to the surface.")
H('104.d.2.K',4,"Efflorescence is caused by water moving through masonry and carrying:","Soluble salts",["Paint","Sugar","Oil"],"Moisture brings salts out.")
H('104.d.2.J',4,"Tempering mortar with a little water is allowed to restore workability but not to:","Exceed the allowed water for the mix",["Dry it faster","Add color","Add sand"],"Excess water weakens.")
H('104.d.2.L',3,"Setting up for mortar work includes placing the mixer, materials, and:","Water source",["Furniture","Paint","Pillow"],"Organize the mixing area.")
H('104.d.2.L',4,"Leftover mortar should be disposed of:","According to site and environmental rules",["Down a storm drain","In the creek","On a neighbor's lawn"],"Proper disposal protects waterways.")
H('104.d.2.M',3,"A clean mixing area helps to avoid:","Contamination and accidents",["Profit","Mortar","Work"],"Housekeeping prevents errors.")
H('104.d.2.M',4,"Washing a mixer's drum at the end of the day prevents:","Hardened mortar buildup",["Quick drying","Rusting only","Rain"],"Clean tools last.")
H('104.d.2.N',3,"The mortar mixing area should be placed:","Close to the work and on firm ground",["Far away","On a slope","Under power lines"],"Efficient layout saves effort.")
H('104.d.2.N',4,"Sand piles at the mixing area should be kept:","Clean and covered when possible",["Dirty","Wet with oil","Open to dogs"],"Protect materials from contamination.")
H('104.d.2.O',3,"When mixing mortar in a power mixer, the dry ingredients are typically added:","With part of the water first, then the rest",["All at once without water","After the mixer is off","Never"],"Staged mixing prevents lumps.")
H('104.d.2.O',4,"Mortar in a power mixer is generally mixed for:","About 3 to 5 minutes",["10 seconds","1 hour","1 day"],"Standard mixing time ensures uniformity.")
H('104.d.3.A',3,"Concrete masonry units usually have:","Hollow cores",["No shape","Solid gold","Wood fibers"],"CMUs are hollow.")
H('104.d.3.A',4,"A standard 8-inch CMU has actual dimensions of about:","7 5/8 by 7 5/8 by 15 5/8 inches",["8 x 8 x 8","4 x 4 x 4","12 x 12 x 12"],"Actual size leaves room for joint.")
H('104.d.3.B',3,"Setting up a CMU wall starts with a:","Dry layout of the first course",["Roof","Door","Window"],"Layout checks fit.")
H('104.d.3.B',4,"In a running bond, vertical joints in each course are:","Offset by half a unit",["Aligned","Random","Absent"],"Staggering distributes loads.")
H('104.d.3.C',3,"Face shell mortar bedding for hollow block means mortar is applied to the:","Outer shells of the block",["Cores","Top only","Inside only"],"Face-shell bedding is typical.")
H('104.d.3.C',4,"Tooling mortar joints is done when mortar is:","Thumbprint hard",["Fully wet","Fully dry","Frozen"],"Timing affects finish.")
H('104.d.3.D',3,"CMU walls are cleaned after the mortar:","Has begun to set but is not fully hard",["Is wet","Is not placed","Has frozen"],"Clean when mortar is partially set.")
H('104.d.3.D',4,"A stiff brush is used to clean CMUs to remove:","Mortar crumbs and residue",["Color","Paint","Texture"],"Brushing cleans faces.")
H('104.d.3.E',3,"Brick is classified by grade, type, and:","Size",["Weight of sand","Brand of mortar","Weather"],"Brick has several classifications.")
H('104.d.3.E',4,"Face brick is used where:","Appearance matters",["Never seen","Hidden walls","Below grade only"],"Face brick is for exposed walls.")
H('104.d.3.F',3,"A dry run for brick laying means:","Placing brick without mortar to check layout",["Wetting the brick","Painting","Finishing"],"Dry bonding checks spacing.")
H('104.d.3.F',4,"The first course of brick is laid in a full mortar bed on the:","Foundation or footing",["Roof","Window","Door"],"The base course sets the line.")
H('104.d.3.G',3,"A mason 'buttering' the end of a brick is:","Applying mortar to the end before placing it",["Painting it","Cutting it","Cleaning it"],"Buttering fills head joints.")
H('104.d.3.G',4,"A convex or V joint tooled in brick is made with a:","Jointer",["Hammer","Saw","Plane"],"Jointers compress mortar.")
H('104.d.3.H',3,"After tooling, excess mortar on brick faces is removed with a:","Brush or cloth",["Hammer","Level","Plane"],"Brushing cleans faces.")
H('104.d.3.H',4,"Acid cleaning of brick should be done with:","Care and protective equipment",["Bare hands","No water","No ventilation"],"Chemicals are hazards.")
H('104.d.3.I',3,"A brick set (wide chisel) and hammer are used to:","Split a brick along a scored line",["Mix mortar","Level a wall","Cut a rule"],"Chisels cut bricks.")
H('104.d.3.I',4,"When cutting with a chisel and hammer, always wear:","Eye protection",["Sandals","A hat only","Nothing"],"Chips fly.")
H('104.d.3.J',3,"A masonry hammer has one square head and a:","Chisel end",["Claw","Saw","Level"],"Used for trimming brick.")
H('104.d.3.J',4,"Light, quick taps with a masonry hammer around a scored line help to:","Break the brick cleanly",["Crush the brick","Mix mortar","Lay the brick"],"Scoring then tapping splits it.")
H('104.d.3.K',3,"A masonry saw cuts with a:","Diamond blade",["Wood blade","Paper blade","Plastic blade"],"Diamond blades cut masonry.")
H('104.d.3.K',4,"A masonry splitter works by:","Applying pressure to split the unit along a line",["Melting it","Burning it","Painting it"],"Splitters break units cleanly.")
H('104.d.3.L',3,"After cutting a unit, check that it:","Fits the space and has clean edges",["Is painted","Is wet","Is lighter"],"Verify fit.")
H('104.d.3.L',4,"A cut brick placed in a wall should have its cut face:","Hidden from view if possible",["Outward always","Unprotected","Painted"],"Cuts are less attractive.")
H('104.d.3.M',3,"Masonry reinforcement such as joint reinforcement is placed in the:","Mortar bed",["Roof","Door","Window"],"Reinforcement strengthens walls.")
H('104.d.3.M',4,"Vertical rebar in CMU walls is placed in:","Grouted cores",["Footings only","Paint","Roofs"],"Cores hold rebar and grout.")
H('104.d.3.N',3,"Masonry accessories such as anchors and ties connect:","The masonry to other building parts",["Colors","Rugs","Paintings"],"Ties anchor masonry.")
H('104.d.3.N',4,"Weep holes in a masonry wall allow:","Moisture to drain out",["Air in only","Sound","Light"],"Weep holes release water.")

H('100.d.1.K',3,"A board falls from a scaffold and hits a worker below. This injury is classified as:","Struck-by",["Electrocution","Caught-in","Slip hazard"],"Impact from a moving object is struck-by.")
H('100.d.1.K',4,"Barricading the area under overhead work mainly prevents which hazard?","Falling-object strikes",["Heat illness","Noise exposure","Chemical burns"],"Keeping people clear stops struck-by injuries.")
H('100.d.5.G',3,"Which document gives the required quality of lumber and fasteners for a house?","Written specifications",["Lunch order","Time sheet","Parking permit"],"Specs state material requirements.")
H('100.d.5.G',4,"Written specifications are read together with the drawings because they give:","Details too long to put on the plans",["Only costs","Only names","Only dates"],"Specs and plans complement each other.")
H('100.d.6.F',3,"Installing bridging in a floor system makes the joists share loads and:","Stay straight",["Rust","Shrink","Glow"],"Bridging holds joists upright.")
H('100.d.6.F',4,"Which is a purpose of herringbone bridging?","Transferring load between neighboring joists",["Holding shingles","Sealing windows","Supporting stairs"],"Bridging spreads loads.")
H('100.d.6.I',3,"Which fastener is best for attaching a subfloor to joists to reduce squeaks?","Screws with construction adhesive",["Staples only","Masking tape","Wire ties"],"Screws and adhesive stop movement.")
H('100.d.6.I',4,"Fastener length for a 3/4-inch subfloor must be long enough to:","Penetrate well into the joist",["Pierce the ceiling","Stay in the panel only","Reach the foundation"],"Embedment gives holding power.")
